query BlockerPlaces($status: String!, $r0Owner: String!, $r0Name: String!, $r1Owner: String!, $r1Name: String!, $r2Owner: String!, $r2Name: String!) {
  r0: repository(owner: $r0Owner, name: $r0Name) {
    i7: issue(number: 7) { ...place }
  }
  r1: repository(owner: $r1Owner, name: $r1Name) {
    i70: issue(number: 70) { ...place }
    i71: issue(number: 71) { ...place }
  }
  r2: repository(owner: $r2Owner, name: $r2Name) {
    i1: issue(number: 1) { ...place }
  }
}

fragment place on Issue {
  state
  projectItems(first: 10) {
    totalCount
    nodes {
      isArchived
      project { id }
      status: fieldValueByName(name: $status) {
        ... on ProjectV2ItemFieldSingleSelectValue { name field { ... on ProjectV2FieldCommon { id } } }
      }
    }
  }
}
